const d = msg.payload;
const cooldown = 60000;
const now = Date.now();
let alerts = [];

const gemelo = global.get('gemelo');
const u = (gemelo && gemelo.umbrales) || {
    co2: { limite: 400 },
    sonido: { limite: 80 },
    distancia: { limite: 20 }
};

if (d.distancia < u.distancia.limite) {
    const last = context.get('d_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Distancia crítica!*\nObjeto a ' + Number(d.distancia).toFixed(1) + ' cm (límite: ' + u.distancia.limite + ' cm)');
        context.set('d_alert', now);
    }
}
if (d.co2 > u.co2.limite) {
    const last = context.get('g_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Nivel de CO2 elevado!*\nValor: ' + d.co2 + ' ppm (límite: ' + u.co2.limite + ' ppm)');
        context.set('g_alert', now);
    }
}
if (d.sonido > u.sonido.limite) {
    const last = context.get('s_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Ruido excesivo!*\n' + d.sonido + '% (límite: ' + u.sonido.limite + '%)');
        context.set('s_alert', now);
    }
}
if (alerts.length > 0) {
    msg.payload = {
        chatId: '1138232122',
        type: 'message',
        content: '🚨 *ALERTA ESTACIÓN IOT*\n\n' + alerts.join('\n\n')
    };
    return msg;
}
return null;

const chatId = msg.payload.chatId || '1138232122';
const cmd = String(msg.payload.content || '').trim().toUpperCase();

let accion = '';
if (cmd === 'ON' || cmd === '1')           accion = 'ON';
else if (cmd === 'OFF' || cmd === '0')    accion = 'OFF';
else if (cmd === 'TOGGLE' || cmd === 'T') accion = 'TOGGLE';
else {
    return [null, {
        payload: { chatId: chatId, type: 'message', content: '❌ Usá: /led ON, /led OFF o /led TOGGLE' }
    }];
}

return [
    { payload: accion },                                        // Output 1 → MQTT
    { payload: { chatId: chatId, type: 'message', content: '✅ LED ' + accion } }  // Output 2 → Telegram
];

const estado = String(msg.payload).toUpperCase();
const icono = estado === 'ON' ? '🟢' : '🔴';
msg.payload = {
    chatId: '1138232122',
    type: 'message',
    content: icono + ' LED ' + (estado === 'ON' ? 'ENCENDIDO' : 'APAGADO')
};
return msg;

const texto = String((msg.payload && msg.payload.content) || '').trim();
const chatId = msg.payload && msg.payload.chatId;
if (!texto || texto.startsWith('/')) return [null, null];

const gemelo = global.get('gemelo');
if (!gemelo) {
    return [null, { payload: { chatId: chatId, type: 'message', content: '⏳ El gemelo digital aún no está inicializado, probá de nuevo en unos segundos.' } }];
}

const e = gemelo.estado_actual;
const u = gemelo.umbrales;

let contexto = 'Datos actuales de los sensores de la casa:\n';
contexto += '- CO2 (sensor MQ7): ' + e.co2 + ' ppm\n';
contexto += '- Distancia (ultrasonico): ' + e.distancia + ' cm\n';
contexto += '- Nivel de sonido: ' + e.sonido + ' dB\n';
contexto += '- Persona detectada por la camara: ' + (e.persona ? ('Si' + (e.persona_nombre ? ', identificada como ' + e.persona_nombre : ', desconocida')) : 'No') + '\n';
contexto += '- LED: ' + (e.led ? 'Encendido' : 'Apagado') + '\n';
contexto += '- Buzzer: ' + (e.buzzer ? 'Activado' : 'Apagado') + '\n\n';
if (u) {
    contexto += 'Umbrales criticos configurados (se considera peligroso al superarlos):\n';
    contexto += '- CO2: mayor a ' + u.co2.limite + ' ppm\n';
    contexto += '- Sonido: mayor a ' + u.sonido.limite + ' dB\n';
    contexto += '- Distancia: menor a ' + u.distancia.limite + ' cm\n\n';
}
contexto += 'Pregunta del usuario: ' + texto;

msg.chatId = chatId;
msg.payload = {
    model: 'llama3.2:3b',
    system: 'Eres el asistente de una casa inteligente. Responde SIEMPRE en espanol, de forma breve, clara y precisa, usando solo los datos de sensores proporcionados. No inventes valores que no esten en el contexto.',
    prompt: contexto,
    stream: false
};
return [msg, null];

const respuesta = (msg.payload && msg.payload.response) || 'No se pudo obtener respuesta del asistente.';
msg.payload = { chatId: msg.chatId, type: 'message', content: respuesta };
return msg;
